-- Idiomas fora do escopo mantêm o texto anterior em português para as novas chaves V3.
for _, locale in ipairs( { 'fr-fr', 'de-de' } ) do
    for key, value in pairs( translations[ 'pt-br' ] ) do
        if key:sub( 1, 11 ) == 'facfoco.v3.' then
            translations[ locale ][ key ] = value
        end
    end
end

